head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDBNF60201";
scwin.dmenus = undefined;
scwin.v_unused_amt = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_sriBndTpCd", fn: function(){ return ((dma_result.get("sriBndTpCd") ?? (() => { throw new Error("unresolved:" + "result.sriBndTpCd"); })()) === '4'); } }, { id: "if_sriBndTpCd_2", fn: function(){ return ((dma_result.get("sriBndTpCd") ?? (() => { throw new Error("unresolved:" + "result.sriBndTpCd"); })()) === '4'); } }, { id: "c_when_131", fn: function(){ return ((dma_result.get("sriBndTpCd") ?? (() => { throw new Error("unresolved:" + "result.sriBndTpCd"); })()) !== '4'); } }, { id: "c_otherwise_170", fn: function(){ return (!(((dma_result.get("sriBndTpCd") ?? (() => { throw new Error("unresolved:" + "result.sriBndTpCd"); })()) !== '4'))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        for (let __r = 0, __n = $c.util.getComponent('dlt_dtlList').getRowCount(); __r < __n; __r++) {let i = __r;

        }
        for (let __r = 0, __n = $c.util.getComponent('dlt_dtlList').getRowCount(); __r < __n; __r++) {let i = __r; /* 수동 전환 필요: DOM 관용구 $(this) 잔존 — 행 순회 안에서 해석 못 함(D19-b) */
            $(this).attr("id", "sri_bnd_prog_stat_cd" + i);
        }
        const sToday = WebSquare.date.getCurrentServerDate("yyyyMMdd");
        const sThisYear = sToday.substring(0, 4);
        $c.util.getComponent('slc_suplyFndUseRptYy').setValue(sThisYear);
        for (let __r = 0, __n = $c.util.getComponent('dlt_dtlList').getRowCount(); __r < __n; __r++) {let i = __r;
            let t = $c.util.getComponent('dlt_dtlList').getCellData(__r, 'lstObservDd');
            t = t.replace(/-/gi, '');
            if (t >= sToday) {
                $("#sri_bnd_prog_stat_cd" + i).val("1");
                $("#sri_bnd_prog_stat_cd" + i + " option[value='2']").remove();
                $("#sri_bnd_prog_stat_cd" + i + " option[value='3']").remove();
            } else {
                $("#sri_bnd_prog_stat_cd" + i + " option:first").remove();
            }
        }
        $('#slc_suplyFndUseRptRndTpCd').change(function() {
                if (this.value === "3") {
                    $('#ipt_efctRptIncldY').prop('checked', true);
                } else {
                    $('#ipt_efctRptIncldN').prop('checked', true);
                }
        });
        $('input[name=efct_rpt_incld_yn_rdo]:radio').change(async function() {
                if (this.value === "Y" && $c.util.getComponent('slc_suplyFndUseRptRndTpCd').getValue() !== "3") {
                    await $c.win.alert("최종보고인 경우만 선택 할 수 있습니다.");
                    $('#ipt_efctRptIncldN').prop('checked', true);
                }
        });

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf60201.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dmenus ={
        "bmenu":9
        ,"mmenu":1
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldbnf60201' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.v_unused_amt = '' + dma_result.get("unusedAmt") + '';
        scwin.init_conds();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf60201.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_mpd_files2_select_onclick
 * @description 「파일선택」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_mpd_files2_select_onclick = function () {
    try { $c.util.onUploadClick($c.util.getComponent('mpd_files2'));
